    int min_diff = std::numeric_limits<int>::max();
    for (int i = 0; i < numCDNs; ++i) {
      int current_load = target_loads[i];
      int diff = std::abs(request.first - current_load);
      if (diff < min_diff) {
        min_diff = diff;
        best_match = i;
      }
    }
